import math
from collections import Counter

def count_distinct_prime_factors(n):
    """Counts omega(n), the number of distinct prime factors of n."""
    if n <= 0:
        return 0
    factors = Counter()
    d = 2
    temp = n
    while d * d <= temp:
        if temp % d == 0:
            factors[d] += 1
            while temp % d == 0:
                temp //= d
        d += 1
    if temp > 1:
        factors[temp] += 1
    return len(factors)

def omega_K(n):
    """Calculates omega(n! / 2023)"""
    if n < 34:
        return None 

    factorial_n = math.factorial(n)
    K = factorial_n // 2023
    return count_distinct_prime_factors(K)

