import sympy

def legendre(n, p):
    """Calculates the exponent of prime p in the prime factorization of n!"""
    return sum(floor(n / (p**i)) for i in range(1, 30))

def omega_k(n):
    """Calculates omega(K) where K = n! / 2023, 2023 = 7 * 17^2."""
    if n < 2:
        return 0

    prime_factors_count = 0

    # Iterate through primes p <= n
    primes = list(sympy.primerange(2, n + 1))

    for p in primes:
        # Calculate v_p(n!)
        vp_n_fact = legendre(n, p)

        # Check if p is a factor of K = n! / 2023
        is_factor = True

        if p == 7:
            # v_7(2023) = 1. K has factor 7 if vp_n_fact >= 2.
            if vp_n_fact < 2:
                is_factor = False
        elif p == 17:
            # v_17(2023) = 2. K has factor 17 if vp_n_fact >= 3.
            if vp_n_fact < 3:
                is_factor = False

        if is_factor:
            prime_factors_count += 1

    return prime_factors_count

